var list = root.querySelector('.t215-liq-feed-list');
var sumEl = root.querySelector('.t215-liq-feed-sum');
var calm = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var books = [['BTC-PERP',61240,1,900],['ETH-PERP',2412.8,2,430],['SOL-PERP',148.62,2,260],['ARB-PERP',0.8241,4,120],['WIF-PERP',2.4187,4,95],['LINK-PERP',17.442,3,140],['AVAX-PERP',31.08,2,110]];
var total = 184.2, raf = 0, timer = 0;
function num(v,d){ return v.toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d}); }
function money(n){ if(n>=1e6) return '$'+(n/1e6).toFixed(2)+'M'; if(n>=1e3) return '$'+(n/1e3).toFixed(1)+'K'; return '$'+Math.round(n); }
function tween(to){
  if(calm){ sumEl.textContent = to.toFixed(1); return; }
  var from = parseFloat(sumEl.textContent) || 0, t0 = 0;
  cancelAnimationFrame(raf);
  raf = requestAnimationFrame(function step(ts){
    if(document.hidden || !root.isConnected){ sumEl.textContent = to.toFixed(1); return; }
    if(!t0) t0 = ts;
    var k = Math.min(1,(ts-t0)/520), e = 1-Math.pow(1-k,3);
    sumEl.textContent = (from+(to-from)*e).toFixed(1);
    if(k<1) raf = requestAnimationFrame(step);
  });
}
function push(){
  var b = books[Math.floor(Math.random()*books.length)];
  var isLong = Math.random() < 0.58;
  var notional = b[3]*1000*(0.22+Math.random()*3.9);
  var px = b[1]*(1+(Math.random()-0.5)*0.005);
  var li = document.createElement('li');
  li.className = 't215-liq-feed-row ' + (isLong ? 't215-liq-feed-row--dn' : 't215-liq-feed-row--up');
  li.innerHTML = '<span class="t215-liq-feed-side">' + (isLong ? '▼ LONG' : '▲ SHORT') + '</span>' +
    '<span class="t215-liq-feed-pair">' + b[0] + '<i class="t215-liq-feed-px">' + num(px,b[2]) + '</i></span>' +
    '<span class="t215-liq-feed-amt">' + money(notional) + '</span>';
  list.insertBefore(li, list.firstChild);
  while(list.children.length > 4) list.removeChild(list.lastChild);
  total += notional/1e6;
  tween(total);
}
for(var i=0;i<4;i++) push();
sumEl.textContent = total.toFixed(1);
(function loop(){
  timer = setTimeout(function(){
    if(!root.isConnected){ clearTimeout(timer); cancelAnimationFrame(raf); return; }
    if(!document.hidden) push();
    loop();
  }, 950 + Math.random()*1500);
})();

