var curve = root.querySelector('.t215-amm-depth-curve');
var slip = root.querySelector('.t215-amm-depth-slip');
var vline = root.querySelector('.t215-amm-depth-vline');
var spot = root.querySelector('.t215-amm-depth-spot');
var mark = root.querySelector('.t215-amm-depth-mark');
var range = root.querySelector('.t215-amm-depth-range');
var szEl = root.querySelector('.t215-amm-depth-sz');
var recvEl = root.querySelector('.t215-amm-depth-recv');
var impEl = root.querySelector('.t215-amm-depth-imp');
var calm = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var X0 = 1200, SPOT = 3375, Y0 = X0*SPOT, K = X0*Y0;
var W = 300, PL = 6, PR = 6, TOP = 6, BOT = 64;
var xmin = X0*0.85, xmax = X0*1.32, ymin = K/xmax, ymax = K/xmin;
function sx(x){ return PL + (x-xmin)/(xmax-xmin)*(W-PL-PR); }
function sy(y){ return BOT - (y-ymin)/(ymax-ymin)*(BOT-TOP); }
var d = '', i, x;
for(i=0;i<=64;i++){ x = xmin + (xmax-xmin)*i/64; d += (i?'L':'M') + sx(x).toFixed(2) + ' ' + sy(K/x).toFixed(2) + ' '; }
curve.setAttribute('d', d.trim());
spot.setAttribute('cx', sx(X0).toFixed(2)); spot.setAttribute('cy', sy(Y0).toFixed(2));
if(!calm){
  var len = curve.getTotalLength();
  curve.style.strokeDasharray = len + ' ' + len;
  curve.style.strokeDashoffset = len;
  requestAnimationFrame(function(){ requestAnimationFrame(function(){ curve.style.strokeDashoffset = '0'; }); });
}
function draw(){
  var dx = parseFloat(range.value);
  var nx = X0 + dx, ny = K/nx, dy = Y0 - ny;
  var exec = dy/dx, impact = (1 - exec/SPOT)*100;
  var mx = sx(nx), my = sy(ny), p = '', j, xx;
  for(j=0;j<=24;j++){ xx = X0 + (nx-X0)*j/24; p += (j?'L':'M') + sx(xx).toFixed(2) + ' ' + sy(K/xx).toFixed(2) + ' '; }
  p += 'L' + mx.toFixed(2) + ' ' + BOT + ' L' + sx(X0).toFixed(2) + ' ' + BOT + ' Z';
  slip.setAttribute('d', p);
  vline.setAttribute('x1', mx.toFixed(2)); vline.setAttribute('x2', mx.toFixed(2));
  vline.setAttribute('y1', my.toFixed(2)); vline.setAttribute('y2', BOT);
  mark.setAttribute('cx', mx.toFixed(2)); mark.setAttribute('cy', my.toFixed(2));
  szEl.textContent = dx.toFixed(0) + ' ETH';
  recvEl.textContent = Math.round(dy).toLocaleString('en-US') + ' USDC';
  impEl.textContent = '▼ ' + impact.toFixed(2) + '% impact';
}
range.addEventListener('input', draw);
draw();

