var nodes = root.querySelectorAll('.t215-bridge-hop-node');
var fill = root.querySelector('.t215-bridge-hop-fill');
var stateEl = root.querySelector('.t215-bridge-hop-state');
var nEl = root.querySelector('.t215-bridge-hop-n');
var timers = [], confTimer = 0;
function at(ms, fn){ timers.push(setTimeout(function(){ if(root.isConnected) fn(); }, ms)); }
function setNode(i, cls){
  nodes[i].className = 't215-bridge-hop-node' + (cls ? ' t215-bridge-hop-node--' + cls : '');
}
function run(){
  var i;
  for(i=0;i<timers.length;i++) clearTimeout(timers[i]);
  timers = []; clearInterval(confTimer);
  root.className = 't215-bridge-hop';
  for(i=0;i<3;i++) setNode(i, '');
  fill.style.width = '0%';
  nEl.textContent = '0';
  stateEl.textContent = 'Locking on Arbitrum';
  setNode(0, 'live');
  at(950, function(){
    setNode(0, 'done'); setNode(1, 'live');
    stateEl.textContent = 'Waiting for confirmations';
    var c = 0;
    confTimer = setInterval(function(){
      if(!root.isConnected){ clearInterval(confTimer); return; }
      c++; nEl.textContent = String(c);
      fill.style.width = (c/12*50).toFixed(1) + '%';
      if(c >= 12) clearInterval(confTimer);
    }, 330);
  });
  at(5300, function(){
    clearInterval(confTimer); nEl.textContent = '12';
    setNode(1, 'done'); setNode(2, 'live');
    fill.style.width = '100%';
    stateEl.textContent = 'Relayer minting on Base';
  });
  at(6900, function(){
    setNode(2, 'done');
    root.className = 't215-bridge-hop t215-bridge-hop--ok';
    stateEl.textContent = '✓ Delivered — 1.2487 ETH';
    nEl.textContent = '12';
  });
  at(10400, run);
}
run();

