var GAS_UNITS = 168000, ETH = 3375.12, GROSS = 2.5*ETH;
var data = [{g:11.4,eta:'~4m 10s'},{g:17.8,eta:'~48s'},{g:26.2,eta:'~11s'}];
var cur = 1, raf = 0, shown = null;
function feeUsd(g){ return g*GAS_UNITS/1e9*ETH; }
function money(n){ return n.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}); }
function paint(fee){ feeEl.textContent = '−$' + money(fee); netEl.textContent = money(GROSS-fee) + ' USDC'; }
function select(i, animate){
  var prevFee = shown === null ? feeUsd(data[cur].g) : shown;
  cur = i;
  var k;
  for(k=0;k<tiers.length;k++) tiers[k].setAttribute('aria-pressed', k===i ? 'true' : 'false');
  var target = feeUsd(data[i].g);
