    netEl.classList.add(target < prevFee ? 't215-gas-quote-net--up' : 't215-gas-quote-net--dn');
  }
  if(!animate || calm || document.hidden){ shown = target; paint(target); return; }
  var t0 = 0;
  cancelAnimationFrame(raf);
  raf = requestAnimationFrame(function step(ts){
    if(document.hidden || !root.isConnected){ shown = target; paint(target); return; }
