var sprEl = root.querySelector('.t215-book-ladder-spr');
var midEl = root.querySelector('.t215-book-ladder-mid');
var mid = 3374.80, STEP = 0.60, HALF = 0.20;
var asks = [], bids = [], timer = 0;
function mk(side){
  var el = document.createElement('div');
  el.className = 't215-book-ladder-row t215-book-ladder-row--' + side;
  el.innerHTML = '<span class="t215-book-ladder-bar"></span><span class="t215-book-ladder-p"></span><span class="t215-book-ladder-s"></span><span class="t215-book-ladder-tt"></span>';
  return { el: el, bar: el.querySelector('.t215-book-ladder-bar'), p: el.querySelector('.t215-book-ladder-p'), s: el.querySelector('.t215-book-ladder-s'), t: el.querySelector('.t215-book-ladder-tt'), sz: 6 + Math.random()*26 };
}
for(var i=0;i<3;i++){ asks.push(mk('ask')); bids.push(mk('bid')); }
for(i=2;i>=0;i--) askBox.appendChild(asks[i].el);
for(i=0;i<3;i++) bidBox.appendChild(bids[i].el);
function money(n,d){ return n.toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d}); }
function render(){
  var maxCum = 0, cum = 0, j;
  for(j=0;j<3;j++){ cum += asks[j].sz; if(cum>maxCum) maxCum = cum; }
  cum = 0;
  for(j=0;j<3;j++){ cum += bids[j].sz; if(cum>maxCum) maxCum = cum; }
  cum = 0;
  for(j=0;j<3;j++){
    cum += asks[j].sz;
    asks[j].p.textContent = money(mid + HALF + j*STEP, 2);
    asks[j].s.textContent = asks[j].sz.toFixed(2);
    asks[j].t.textContent = cum.toFixed(1);
    asks[j].bar.style.width = (cum/maxCum*100).toFixed(1) + '%';
  }
  cum = 0;
  for(j=0;j<3;j++){
    cum += bids[j].sz;
    bids[j].p.textContent = money(mid - HALF - j*STEP, 2);
    bids[j].s.textContent = bids[j].sz.toFixed(2);
    bids[j].t.textContent = cum.toFixed(1);
    bids[j].bar.style.width = (cum/maxCum*100).toFixed(1) + '%';
  }
