}
function tick(){
  var n = 1 + Math.floor(Math.random()*2), k;
  for(k=0;k<n;k++){
    var side = Math.random() < 0.5 ? asks : bids;
    var row = side[Math.floor(Math.random()*3)];
    row.sz = Math.max(1.4, row.sz + (Math.random()-0.45)*11);
    hit(row);
  }
  if(Math.random() < 0.42){
    var up = Math.random() < 0.5;
    mid = Math.round((mid + (up ? 1 : -1) * (0.1 + Math.random()*0.5))*100)/100;
