    void midEl.offsetWidth;
    midEl.className = 't215-book-ladder-mid t215-book-ladder-mid--' + (up ? 'up' : 'dn');
    arwEl.textContent = up ? '▲' : '▼';
  }
  render();
}
render();
(function loop(){
  timer = setTimeout(function(){
    if(!root.isConnected){ clearTimeout(timer); return; }
    if(!document.hidden) tick();
    loop();
  }, 700 + Math.random()*700);
})();

