pools.forEach(function(p){
  var tr = document.createElement('tr');
  tr.className = 't215-yield-rank-row';
  tr.innerHTML = '<td class="t215-yield-rank-td t215-yield-rank-td--l"><span class="t215-yield-rank-pool"><span class="t215-yield-rank-chip"></span><span class="t215-yield-rank-nm">' + p.name + '</span></span></td>' +
