    '<td class="t215-yield-rank-td"><span class="t215-yield-rank-d7 t215-yield-rank-d7--' + (p.d7 >= 0 ? 'up' : 'dn') + '">' + (p.d7 >= 0 ? '▲' : '▼') + ' ' + Math.abs(p.d7).toFixed(2) + '</span></td>' +
