var steps = root.querySelectorAll('.t215-wallet-fsm-step');
var fill = root.querySelector('.t215-wallet-fsm-fill');
var msg = root.querySelector('.t215-wallet-fsm-msg');
var btn = root.querySelector('.t215-wallet-fsm-btn');
var timers = [];
var S = {
  idle:      {i:0, p:0,   flag:'',     msg:'Wallet detected — not connected', btn:'Connect wallet', on:true},
  approving: {i:1, p:0.333, flag:'busy', msg:'Approve connection in MetaMask', btn:'Waiting…', on:false},
  signing:   {i:2, p:0.666, flag:'busy', msg:'Sign message to verify ownership', btn:'Check your wallet', on:false},
  ready:     {i:3, p:1,   flag:'ok',   msg:'0x7a3f…9c21 <b class="t215-wallet-fsm-bal">2.481 ETH ▲ 1.24%</b>', btn:'Disconnect', on:true},
  rejected:  {i:1, p:0.333, flag:'err',  msg:'User rejected the request (4001)', btn:'Retry', on:true}
};
var state = 'idle';
function clear(){ timers.forEach(clearTimeout); timers = []; }
function later(ms, fn){ timers.push(setTimeout(function(){ if(root.isConnected) fn(); }, ms)); }
function go(next){
  state = next;
  var s = S[next], k;
  root.className = 't215-wallet-fsm' + (s.flag ? ' t215-wallet-fsm--' + s.flag : '');
  fill.style.width = (s.p*100) + '%';
  for(k=0;k<steps.length;k++){
    steps[k].className = 't215-wallet-fsm-step' + (k < s.i ? ' t215-wallet-fsm-step--done' : (k === s.i ? ' t215-wallet-fsm-step--on' : ''));
  }
  msg.innerHTML = s.msg;
  msg.style.animation = 'none';
  void msg.offsetWidth;
  msg.style.animation = '';
  btn.textContent = s.btn;
  btn.disabled = !s.on;
  if(next === 'approving') later(1250, function(){ go(Math.random() < 0.28 ? 'rejected' : 'signing'); });
  if(next === 'signing') later(1450, function(){ go('ready'); });
}
btn.addEventListener('click', function(){
  clear();
  if(state === 'ready') go('idle'); else go('approving');
});
go('idle');

