var line = root.querySelector('.t215-il-curve-line');
var drop = root.querySelector('.t215-il-curve-drop');
var dot = root.querySelector('.t215-il-curve-dot');
var valEl = root.querySelector('.t215-il-curve-val');
var lpEl = root.querySelector('.t215-il-curve-lp');
var hdEl = root.querySelector('.t215-il-curve-hd');
var lpBar = root.querySelector('.t215-il-curve-bf--lp');
var hdBar = root.querySelector('.t215-il-curve-bf--hd');
var chips = root.querySelectorAll('.t215-il-curve-chip');
var calm = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var V0 = 10000, L0 = Math.log(0.16), L1 = Math.log(7), TOP = 7, BOT = 56, XL = 3, XR = 113, MAXIL = 32;
function il(r){ return 2*Math.sqrt(r)/(1+r) - 1; }
function px(r){ return XL + (Math.log(r)-L0)/(L1-L0)*(XR-XL); }
function py(v){ return TOP + Math.min(1, -v*100/MAXIL)*(BOT-TOP); }
var d = '', i, rr;
for(i=0;i<=56;i++){ rr = Math.exp(L0 + (L1-L0)*i/56); d += (i?'L':'M') + px(rr).toFixed(2) + ' ' + py(il(rr)).toFixed(2) + ' '; }
line.setAttribute('d', d.trim());
if(!calm){
  var len = line.getTotalLength();
  line.style.strokeDasharray = len + ' ' + len;
  line.style.strokeDashoffset = len;
  requestAnimationFrame(function(){ requestAnimationFrame(function(){ line.style.strokeDashoffset = '0'; }); });
}
var target = 2, vel = 0, pos = 2, raf = 0;
function paint(r){
  var loss = il(r), lp = V0*Math.sqrt(r), hd = V0*(1+r)/2, mx = Math.max(lp, hd);
  valEl.textContent = (loss < -0.00005 ? '−' : '') + Math.abs(loss*100).toFixed(2);
  lpEl.textContent = Math.round(lp).toLocaleString('en-US');
  hdEl.textContent = Math.round(hd).toLocaleString('en-US');
  lpBar.style.width = (lp/mx*100).toFixed(1) + '%';
  hdBar.style.width = (hd/mx*100).toFixed(1) + '%';
  var x = px(r), y = py(loss);
  dot.setAttribute('cx', x.toFixed(2)); dot.setAttribute('cy', y.toFixed(2));
  drop.setAttribute('x1', x.toFixed(2)); drop.setAttribute('x2', x.toFixed(2));
  drop.setAttribute('y1', TOP.toFixed(2)); drop.setAttribute('y2', y.toFixed(2));
}
function spring(){
  raf = requestAnimationFrame(function(){
    if(!root.isConnected) return;
    if(document.hidden){ pos = target; paint(pos); return; }
    var lp = Math.log(pos), lt = Math.log(target);
    vel += (lt - lp)*0.16;
    vel *= 0.76;
    pos = Math.exp(lp + vel);
    paint(pos);
    if(Math.abs(lt - Math.log(pos)) > 0.0008 || Math.abs(vel) > 0.0008) spring();
    else { pos = target; paint(pos); }
  });
}
function pick(btn){
  var k;
  for(k=0;k<chips.length;k++) chips[k].setAttribute('aria-pressed', chips[k] === btn ? 'true' : 'false');
  target = parseFloat(btn.getAttribute('data-r'));
  if(calm || document.hidden){ pos = target; paint(pos); return; }
  cancelAnimationFrame(raf); vel = 0; spring();
}
for(var c=0;c<chips.length;c++){
  (function(btn){ btn.addEventListener('click', function(){ pick(btn); }); })(chips[c]);
}
paint(2);
